import pandas as pd

# Define source file paths
source_files = [
    "autopipeline-benchmarks/github-pipelines/length4_70/test_0.csv",
    "autopipeline-benchmarks/github-pipelines/length4_70/test_1.csv",
    "autopipeline-benchmarks/github-pipelines/length4_70/test_2.csv",
    "autopipeline-benchmarks/github-pipelines/length4_70/test_3.csv",
    "autopipeline-benchmarks/github-pipelines/length4_70/test_4.csv"
]

# List to hold dataframes
dfs = []

for file_path in source_files:
    # Read CSV with index_col=0 to ignore the numerical index column
    df = pd.read_csv(file_path, index_col=0)

    # The first row in each source file is a header row with descriptive text, not data
    # Remove that first row if it contains non-numeric or non-valid data in key columns
    # Check if first row is header-like by checking if 'GEO.id' column value is 'Id' (string)
    if df.iloc[0]['GEO.id'] == 'Id':
        df = df.iloc[1:].copy()

    # Convert columns to correct types and formats according to target schema:
    # Target schema: ['GEO.id': string, 'GEO.id2': string, 'GEO.display-label': string, 'HD01_VD01': string, 'HD02_VD01': string, 'Year': integer]

    # GEO.id: keep as string
    df['GEO.id'] = df['GEO.id'].astype(str)

    # GEO.id2: convert to string (source has float, target expects string)
    # Some values might be float strings like '72459.0', convert to int first then string without decimal
    def convert_geo_id2(val):
        try:
            f = float(val)
            i = int(f)
            return str(i)
        except:
            return str(val)
    df['GEO.id2'] = df['GEO.id2'].apply(convert_geo_id2)

    # GEO.display-label: keep as string
    df['GEO.display-label'] = df['GEO.display-label'].astype(str)

    # HD01_VD01: source has numeric values but stored as float or string, target expects string
    # Convert to float first, then to int if possible, then to string without decimal if integer
    def convert_hd01(val):
        try:
            f = float(val)
            if f.is_integer():
                return str(int(f))
            else:
                return str(f)
        except:
            # If conversion fails, keep original string (e.g. if empty or invalid)
            return str(val)
    df['HD01_VD01'] = df['HD01_VD01'].apply(convert_hd01)

    # HD02_VD01: same as HD01_VD01, convert to string with no decimal if integer
    def convert_hd02(val):
        try:
            f = float(val)
            if f.is_integer():
                return str(int(f))
            else:
                return str(f)
        except:
            return str(val)
    df['HD02_VD01'] = df['HD02_VD01'].apply(convert_hd02)

    # Year: convert to integer
    # Some source Year columns might be string or float, convert safely
    def convert_year(val):
        try:
            return int(float(val))
        except:
            # If conversion fails, set as NaN (will drop later)
            return pd.NA
    df['Year'] = df['Year'].apply(convert_year)

    # Drop rows where Year is NA (invalid)
    df = df.dropna(subset=['Year'])

    # Reset index after filtering
    df = df.reset_index(drop=True)

    # Append cleaned dataframe to list
    dfs.append(df)

# UNION operation: concatenate all dataframes vertically
target_df = pd.concat(dfs, ignore_index=True)

# Reorder columns to match target schema exactly
target_columns = ['GEO.id', 'GEO.id2', 'GEO.display-label', 'HD01_VD01', 'HD02_VD01', 'Year']
target_df = target_df[target_columns]

# Ensure Year column is integer dtype
target_df['Year'] = target_df['Year'].astype(int)

# Write the result to the target CSV file without the index
target_df.to_csv("autopipeline-benchmarks/github-pipelines/length4_70/target_multisource.csv", index=False)
